    @Test fun icing_then_clear_sky() {
        val s = initialSimState().apply { battery = true; psFlightAltFt = 10000.0; psFlightCasKt = 280.0; wow = false }
        var st = s
        for (i in 0 until 900) { st = tickOnce(st, 0.03333333333333333, if (i >= 450) 0.0 else 0.5) }
