    @Test fun pack_overheat_trip_latched() {
        val s = initialSimState().apply { battery = true; apuMaster = "ON"; apuRpm = 100.0; apuOilPsi = 95.0; apuFuelValve = 1.0; apuDoor = 1.0; apuGen = true; apuLeftControl = true; apuBleed = true; apuBleedValve = 1.0; packL = true; packR = true; faults.packOverheat = true }
        var st = s
        repeat(600) { st = tickOnce(st, 0.03333333333333333, 0.0) }
        assertEquals("battery", true, (st.battery ?: !true))
        assertEquals("timeScale", 4.0, (st.timeScale ?: Double.NaN), 1e-6)
        assertEquals("apuMaster", "ON", (st.apuMaster ?: "<null>"))
        assertEquals("apuBleed", true, (st.apuBleed ?: !true))
