    @Test fun bleed1_overheat_trip() {
        val s = initialSimState().apply { battery = true; apuMaster = "ON"; apuRpm = 100.0; apuOilPsi = 95.0; apuFuelValve = 1.0; apuDoor = 1.0; apuGen = true; apuLeftControl = true; apuBleed = true; apuBleedValve = 1.0; packL = true; packR = true; faults.bleedOverheat1 = true }
        var st = s
        repeat(600) { st = tickOnce(st, 0.03333333333333333, 0.0) }
        assertEquals("battery", true, (st.battery ?: !true))
        assertEquals("timeScale", 4.0, (st.timeScale ?: Double.NaN), 1e-6)
        assertEquals("apuMaster", "ON", (st.apuMaster ?: "<null>"))
        assertEquals("apuBleed", true, (st.apuBleed ?: !true))
        assertEquals("apuGen", true, (st.apuGen ?: !true))
        assertEquals("apuLeftControl", true, (st.apuLeftControl ?: !true))
        assertEquals("apuRightControl", false, (st.apuRightControl ?: !false))
        assertEquals("apuFirePulled", false, (st.apuFirePulled ?: !false))
        assertEquals("apuBottleFired", false, (st.apuBottleFired ?: !false))
        assertEquals("wheelWellFire", false, (st.wheelWellFire ?: !false))
        assertEquals("wheelWellLevel", 0.0, (st.wheelWellLevel ?: Double.NaN), 1e-6)
        assertEquals("cargoFwdFire", false, (st.cargoFwdFire ?: !false))
        assertEquals("cargoAftFire", false, (st.cargoAftFire ?: !false))
        assertEquals("cargoFwdLevel", 0.0, (st.cargoFwdLevel ?: Double.NaN), 1e-6)
        assertEquals("cargoAftLevel", 0.0, (st.cargoAftLevel ?: Double.NaN), 1e-6)
        assertEquals("cargoArmed", "NONE", (st.cargoArmed ?: "<null>"))
        assertEquals("cargoBottleDischarged", false, (st.cargoBottleDischarged ?: !false))
        assertEquals("cargoAgentTimer", 0.0, (st.cargoAgentTimer ?: Double.NaN), 1e-6)
        assertEquals("cargoFireInstalled", true, (st.cargoFireInstalled ?: !true))
        assertEquals("cargoLoopA", true, (st.cargoLoopA ?: !true))
        assertEquals("cargoLoopB", true, (st.cargoLoopB ?: !true))
