    @Test fun rto_full_stop_autobrake() {
        val s = initialSimState().apply { battery = true; wow = true; hydAPress = 3000.0; hydBPress = 3000.0; rwyPhase = "ROLLOUT"; groundSpeedKt = 60.0; rwyPosM = 500.0; autobrake = 4.0; antiskidInbd = true; antiskidOutbd = true; speedBrake = "ARMED"; throttle1 = 0.0; throttle2 = 0.0 }
        var st = s
        repeat(2400) { st = tickOnce(st, 0.03333333333333333, 0.0) }
        assertEquals("battery", true, (st.battery ?: !true))
        assertEquals("timeScale", 4.0, (st.timeScale ?: Double.NaN), 1e-6)
        assertEquals("apuMaster", "OFF", (st.apuMaster ?: "<null>"))
        assertEquals("apuBleed", false, (st.apuBleed ?: !false))
        assertEquals("apuGen", false, (st.apuGen ?: !false))
        assertEquals("apuLeftControl", false, (st.apuLeftControl ?: !false))
